-- LPCFG: live-prep's fills of 2026-10-09, read-only, with whether each is of the YES token; saved and cut out as minutes.sql.
select jsonb_build_object('pad', repeat('x', 300000), 'fills', (select jsonb_agg(jsonb_build_array(f.match_time, left(f.cond,10), f.token = m.yes_token, f.side, f.price, f.size, f.status) order by f.match_time) from public.pm_lp_fills f left join lateral (select yes_token from public.pm_lp_markets x where x.cond = f.cond order by day desc limit 1) m on true where f.match_time >= '2026-10-09T00:00:00Z' and f.match_time < '2026-10-10T00:00:00Z')) payload
